-- GENERATED by `wfj generate` from data/book/. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("book", {
  ["121caa0f16ec0750"] = { "Con il passare delle settimane la nostra scorta di pelli di pantera e di tigre crebbe a dismisura. Decisi che era tempo che la spedizione si dedicasse a una nuova sfida: i raptor.\n\nGli Umani, pur apprezzando l'addestramento che Barnil e io avevamo offerto loro, decisero di rinunciare a cacciare con le armi da fuoco. Ajeck si trovava molto più a suo agio con un arco ben teso e Sir Erlgadin non lasciava mai il campo senza la sua robusta balestra.", "." },
  ["122d36584a5a32fa"] = { "Dopo alcuni anni, il grosso dell'⟦Horde=Orda⟧ degli orchi era passato su Azeroth, e Gul'dan giudicò che fosse giunto il momento dell'attacco principale contro l'umanità. L'⟦Horde=Orda⟧ scagliò tutta la sua potenza contro l'ignaro regno di ⟦Stormwind=Roccavento⟧.", "." },
  ["1235c849433703a4"] = { "Lord Bethor Iceshard,\n\ncome da tue istruzioni, ti invio l'agente che hai richiesto. È il latore di questo biglietto.\n\nQuesta persona si è dimostrata affidabile e capace di eseguire gli ordini, ha dato prova di sé contro le forze del Flagello ed è la mia scelta per la tua missione.\n\nChe Lei regni suprema,\n-Magistrato Sevren", "." },
  ["1242b084e935cea8"] = { "-Perfettamente rotondo, dal pugno al gomito.\n\n-Borchie lungo il bordo. D'argento.\n\n-Una grande borchia al centro, larga tre dita. D'argento.\n\n-Di quercia, rinforzato con ferro.\n\n-Il mio nome, Gringer Stormpike, inciso lungo il bordo superiore.", "." },
  ["126357f0bfd961ca"] = { "Benché i poteri quasi illimitati di Sargeras fossero più che sufficienti a sconfiggere i vili eredar, egli era profondamente turbato dalla corruzione e dalla malvagità totale di quelle creature. Incapace di comprendere una simile depravazione, il grande ⟦Titan=Titano⟧ cominciò a scivolare in una cupa depressione. Nonostante il crescente turbamento, Sargeras liberò l'universo dagli stregoni intrappolandoli in un angolo della ⟦Twisting Nether=Distorsione Fatua⟧.", "." },
  ["12635a42807e8ec4"] = { "Gli orchi di Draenor (il mondo da cui provenivano in origine) erano nobili e seguivano lo sciamanesimo. Erano guerrieri possenti, forti nel corpo e nella volontà. Fu per queste ragioni che la Legione Infuocata li cercò. Kil'jaeden, un demone di grande potere tra le file della Legione, voleva schiavizzare i clan degli orchi e usarli come suo esercito contro i mondi che la Legione Infuocata doveva ancora conquistare.", "." },
  ["126be89c6e6bf876"] = { "il benedetto. Non tutti gli ⟦Highborne=Alti Nobili⟧ combatterono. Alcuni restarono immobili, come pietrificati, mentre la follia li prendeva. Città possenti e umili villaggi cadevano allo stesso modo attorno a loro.\n\nAd ⟦Ameth'Aran=Ameth'aran⟧ tutto era in rovina, e la sua gente si aggrappava al suolo come se ciò potesse risparmiarla dalla distruzione. Fu allora che Athrikus Narassin, prediletto di Azshara, apparve per guidarli in salvo.\n\nCon un incantesimo poteva proteggerli, diceva. Mentre attorno a loro fratelli e sorelle, padri e madri perivano,", "." },
  ["12ccd7f840c8903f"] = { "Saluti. Ho finalmente trovato il tempo di esaminare quella missiva che hai trovato addosso al Flagello. Non è stato facile, ma credo di aver scoperto un parente ancora in vita del defunto.\n\nLa sorella di Maxwell, una certa Zarena Cromwind, gestisce una piccola armeria a ⟦Booty Bay=Baia del Bottino⟧. Non so quanto fosse legata al fratello, ma se ti capita di passare di lì, dovresti organizzare un incontro. Di questi tempi, mettere la parola fine a certe faccende è un dono prezioso e raro.", "." },
})
